{
  "name": "WhatsDoc Flow",
  "description": "A dual-interface platform for customer registration and automated WhatsApp document delivery via n8n integration."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface CustomerRequest {
  id: string;
  customerName: string;
  phoneNumber: string;
  videoName: string; // This is the key identifier
  status: 'pending' | 'processing' | 'completed' | 'failed';
  requestedAt: string; // ISO Date string
}

export interface UploadStatus {
  fileName: string;
  progress: number;
  status: 'idle' | 'uploading' | 'success' | 'error';
  message?: string;
}

export interface N8nConfig {
  webhookBaseUrl: string;
  useMockMode: boolean;
}

import { N8nConfig } from './types';

// CONFIGURATION
// ------------------------------------------------------------------
// Replace 'YOUR_N8N_WEBHOOK_URL_HERE' with your actual Cloudflare tunnel URL
// e.g., "https://n8n.yourdomain.com/webhook"
// ------------------------------------------------------------------

export const APP_CONFIG: N8nConfig = {
  // If true, the app uses local browser storage to simulate the backend.
  // Set to FALSE to connect to your real n8n server.
  useMockMode: true, 

  // The Base URL for your n8n webhooks.
  // The app expects two endpoints:
  // 1. POST /register-customer
  // 2. POST /upload-document
  webhookBaseUrl: "https://your-n8n-instance.com/webhook",
};

export const MOTIVATIONAL_QUOTES = [
  "Great work! You're making customers happy.",
  "Keep up the momentum!",
  "Another video delivered, another memory shared.",
  "Efficiency is doing better what is already being done.",
  "Your speed is impressive today!",
];

import { APP_CONFIG } from '../constants';
import { CustomerRequest } from '../types';

// Helper to simulate delay
const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

// MOCK STORAGE KEY
const STORAGE_KEY = 'whatsdoc_mock_db';

const getMockData = (): CustomerRequest[] => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

const setMockData = (data: CustomerRequest[]) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

// --- API METHODS ---

/**
 * Registers a new customer request.
 * Mobile Portal calls this.
 */
export const registerCustomer = async (
  name: string,
  phone: string,
  videoName: string
): Promise<boolean> => {
  if (APP_CONFIG.useMockMode) {
    await delay(800);
    const current = getMockData();
    const newRequest: CustomerRequest = {
      id: Math.random().toString(36).substr(2, 9),
      customerName: name,
      phoneNumber: phone,
      videoName: videoName.trim(),
      status: 'pending',
      requestedAt: new Date().toISOString(),
    };
    setMockData([...current, newRequest]);
    return true;
  } else {
    // REAL N8N CALL
    try {
      const response = await fetch(`${APP_CONFIG.webhookBaseUrl}/register-customer`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, phone, videoName }),
      });
      return response.ok;
    } catch (error) {
      console.error("API Error", error);
      return false;
    }
  }
};

/**
 * Fetches the list of pending requests.
 * Desktop Dashboard calls this.
 */
export const getPendingRequests = async (): Promise<CustomerRequest[]> => {
  if (APP_CONFIG.useMockMode) {
    await delay(500);
    const all = getMockData();
    // Sort: Oldest pending first
    return all
      .filter((r) => r.status === 'pending')
      .sort((a, b) => new Date(a.requestedAt).getTime() - new Date(b.requestedAt).getTime());
  } else {
    // REAL N8N CALL
    // You need a GET webhook in n8n that returns the database rows
    try {
      const response = await fetch(`${APP_CONFIG.webhookBaseUrl}/get-pending`);
      const data = await response.json();
      return data;
    } catch (error) {
      console.error("API Error", error);
      return [];
    }
  }
};

/**
 * Uploads a file for a specific customer.
 * Desktop Dashboard calls this when a match is found.
 */
export const uploadDocument = async (
  requestId: string,
  file: File,
  phoneNumber: string
): Promise<boolean> => {
  if (APP_CONFIG.useMockMode) {
    await delay(2000); // Simulate upload time
    const all = getMockData();
    const updated = all.map((r) =>
      r.id === requestId ? { ...r, status: 'completed' as const } : r
    );
    setMockData(updated);
    return true;
  } else {
    // REAL N8N CALL
    // We send FormData to handle the binary file
    const formData = new FormData();
    formData.append('file', file);
    formData.append('requestId', requestId);
    formData.append('phoneNumber', phoneNumber);
    formData.append('videoName', file.name);

    try {
      const response = await fetch(`${APP_CONFIG.webhookBaseUrl}/upload-document`, {
        method: 'POST',
        body: formData, // fetch automatically sets Content-Type to multipart/form-data
      });
      return response.ok;
    } catch (error) {
      console.error("API Error", error);
      return false;
    }
  }
};

import React, { useState } from 'react';
import { User, Phone, Video, CheckCircle, Loader2 } from 'lucide-react';
import { registerCustomer } from '../services/api';

const MobileRegister: React.FC = () => {
  const [formData, setFormData] = useState({ name: '', phone: '', videoName: '' });
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success'>('idle');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.phone || !formData.videoName) return;

    setStatus('submitting');
    const success = await registerCustomer(formData.name, formData.phone, formData.videoName);

    if (success) {
      setStatus('success');
      // Reset form after 3 seconds
      setTimeout(() => {
        setFormData({ name: '', phone: '', videoName: '' });
        setStatus('idle');
      }, 3000);
    } else {
      alert("Failed to register. Please try again.");
      setStatus('idle');
    }
  };

  if (status === 'success') {
    return (
      <div className="min-h-screen bg-green-50 flex flex-col items-center justify-center p-6 text-center">
        <div className="bg-white p-8 rounded-full shadow-lg mb-6">
          <CheckCircle className="w-16 h-16 text-green-500" />
        </div>
        <h2 className="text-2xl font-bold text-gray-800 mb-2">Registration Complete!</h2>
        <p className="text-gray-600">
          We will send <strong>{formData.videoName}</strong> to {formData.name} via WhatsApp shortly.
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col justify-center py-12 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md px-4">
        <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
          Customer Check-In
        </h2>
        <p className="mt-2 text-center text-sm text-gray-600">
          Register to receive your video document.
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md px-4">
        <div className="bg-white py-8 px-4 shadow sm:rounded-lg sm:px-10">
          <form className="space-y-6" onSubmit={handleSubmit}>

            {/* Name Input */}
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-gray-700">
                Full Name
              </label>
              <div className="mt-1 relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  name="name"
                  required
                  className="focus:ring-blue-500 focus:border-blue-500 block w-full pl-10 sm:text-sm border-gray-300 rounded-md py-3 border"
                  placeholder="John Doe"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </div>
            </div>

            {/* Phone Input */}
            <div>
              <label htmlFor="phone" className="block text-sm font-medium text-gray-700">
                WhatsApp Number
              </label>
              <div className="mt-1 relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Phone className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="tel"
                  name="phone"
                  required
                  className="focus:ring-blue-500 focus:border-blue-500 block w-full pl-10 sm:text-sm border-gray-300 rounded-md py-3 border"
                  placeholder="+1 234 567 890"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                />
              </div>
            </div>

            {/* Video Name Input */}
            <div>
              <label htmlFor="videoName" className="block text-sm font-medium text-gray-700">
                Video/Document Name
              </label>
              <div className="mt-1 relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Video className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  name="videoName"
                  required
                  className="focus:ring-blue-500 focus:border-blue-500 block w-full pl-10 sm:text-sm border-gray-300 rounded-md py-3 border"
                  placeholder="e.g. wedding_party_01"
                  value={formData.videoName}
                  onChange={(e) => setFormData({ ...formData, videoName: e.target.value })}
                />
              </div>
              <p className="mt-2 text-xs text-gray-500">
                * This must match the file name uploaded later exactly.
              </p>
            </div>

            <div>
              <button
                type="submit"
                disabled={status === 'submitting'}
                className="w-full flex justify-center py-3 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 transition-colors"
              >
                {status === 'submitting' ? (
                  <Loader2 className="animate-spin h-5 w-5" />
                ) : (
                  "Register Customer"
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default MobileRegister;

import React, { useState, useEffect, useCallback } from 'react';
import { UploadCloud, Clock, CheckCircle, RefreshCw, FileVideo, AlertCircle } from 'lucide-react';
import { CustomerRequest } from '../types';
import { getPendingRequests, uploadDocument } from '../services/api';
import { formatDistanceToNow } from 'date-fns';
import { MOTIVATIONAL_QUOTES } from '../constants';

const DesktopDashboard: React.FC = () => {
  const [requests, setRequests] = useState<CustomerRequest[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);
  const [motivation, setMotivation] = useState(MOTIVATIONAL_QUOTES[0]);

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    const data = await getPendingRequests();
    setRequests(data);
    setIsLoading(false);
  }, []);

  useEffect(() => {
    fetchData();
    // Poll every 10 seconds for new registrations
    const interval = setInterval(fetchData, 10000);
    return () => clearInterval(interval);
  }, [fetchData]);

  // Handle File Upload & Logic Match
  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Normalize filename (remove extension for matching)
    const rawFileName = file.name;
    const nameWithoutExt = rawFileName.substring(0, rawFileName.lastIndexOf('.')) || rawFileName;

    // FIND MATCH
    // We look for a pending request where the videoName is contained in the uploaded filename
    const match = requests.find(r => 
      r.status === 'pending' && 
      (nameWithoutExt.toLowerCase().includes(r.videoName.toLowerCase()) || 
       r.videoName.toLowerCase() === nameWithoutExt.toLowerCase())
    );

    if (match) {
      setUploadStatus(`Matching "${match.customerName}"... Uploading...`);
      const success = await uploadDocument(match.id, file, match.phoneNumber);

      if (success) {
        setUploadStatus(`Success! Sent to ${match.customerName}.`);
        setMotivation(MOTIVATIONAL_QUOTES[Math.floor(Math.random() * MOTIVATIONAL_QUOTES.length)]);
        await fetchData(); // Refresh list
        setTimeout(() => setUploadStatus(null), 3000);
      } else {
        setUploadStatus("Error: Failed to upload.");
      }
    } else {
      setUploadStatus(`No pending request matches file "${rawFileName}". Check spelling.`);
    }

    // Reset input
    e.target.value = '';
  };

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">

      {/* SIDEBAR: PENDING REQUESTS */}
      <div className="w-1/3 bg-white border-r border-gray-200 flex flex-col">
        <div className="p-5 border-b border-gray-200 bg-gray-50 flex justify-between items-center">
          <div>
            <h2 className="text-lg font-bold text-gray-800">Pending Queue</h2>
            <p className="text-sm text-gray-500">{requests.length} waiting for video</p>
          </div>
          <button onClick={fetchData} className="p-2 hover:bg-gray-200 rounded-full transition">
            <RefreshCw className={`w-5 h-5 text-gray-600 ${isLoading ? 'animate-spin' : ''}`} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-3">
          {requests.length === 0 ? (
            <div className="text-center py-10 text-gray-400">
              <CheckCircle className="w-12 h-12 mx-auto mb-2 opacity-50" />
              <p>All caught up! No pending requests.</p>
            </div>
          ) : (
            requests.map((req) => (
              <div key={req.id} className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm hover:shadow-md transition-shadow relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-1 h-full bg-orange-400"></div>
                <div className="ml-3">
                  <div className="flex justify-between items-start">
                    <h3 className="font-semibold text-gray-800">{req.customerName}</h3>
                    <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-600">
                      {req.videoName}
                    </span>
                  </div>
                  <div className="mt-2 flex items-center text-sm text-gray-500 space-x-4">
                    <span className="flex items-center">
                      <Clock className="w-3 h-3 mr-1" />
                      {formatDistanceToNow(new Date(req.requestedAt), { addSuffix: true })}
                    </span>
                    <span>{req.phoneNumber}</span>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* MAIN AREA: UPLOADER */}
      <div className="flex-1 flex flex-col p-8 relative">

        {/* TOP BAR: STATS & MOTIVATION */}
        <div className="mb-8 flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Upload Dashboard</h1>
            <p className="text-gray-500 mt-1">AWS T3 Small • n8n Connected</p>
          </div>

          <div className="bg-blue-600 text-white px-6 py-3 rounded-lg shadow-lg max-w-md animate-pulse">
             <p className="font-medium">✨ {motivation}</p>
          </div>
        </div>

        {/* UPLOAD ZONE */}
        <div className="flex-1 bg-white rounded-2xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center p-10 hover:border-blue-500 hover:bg-blue-50 transition-colors cursor-pointer relative group">
          <input 
            type="file" 
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            onChange={handleFileChange}
            accept="video/*,application/pdf,image/*"
          />

          <div className="text-center pointer-events-none transition-transform group-hover:scale-105 duration-200">
            <div className="bg-blue-100 p-6 rounded-full inline-block mb-4">
              <UploadCloud className="w-16 h-16 text-blue-600" />
            </div>
            <h3 className="text-2xl font-bold text-gray-800 mb-2">Drop Video File Here</h3>
            <p className="text-gray-500 max-w-md mx-auto">
              System will automatically match the filename with the "Pending Queue" on the left and send via WhatsApp.
            </p>
          </div>

          {/* UPLOAD STATUS OVERLAY */}
          {uploadStatus && (
            <div className="absolute inset-0 bg-white/90 z-20 flex flex-col items-center justify-center backdrop-blur-sm rounded-2xl">
              {uploadStatus.includes("Error") || uploadStatus.includes("No pending") ? (
                 <AlertCircle className="w-16 h-16 text-red-500 mb-4" />
              ) : (
                 <Loader2 className="w-16 h-16 text-blue-600 animate-spin mb-4" />
              )}
              <h3 className={`text-xl font-bold ${uploadStatus.includes("Error") ? 'text-red-600' : 'text-gray-800'}`}>
                {uploadStatus}
              </h3>
            </div>
          )}
        </div>

        <div className="mt-6 grid grid-cols-3 gap-6">
           <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-100 flex items-center">
              <div className="bg-orange-100 p-3 rounded-md mr-4">
                <Clock className="text-orange-600 w-6 h-6" />
              </div>
              <div>
                <p className="text-sm text-gray-500">Pending</p>
                <p className="text-xl font-bold">{requests.length}</p>
              </div>
           </div>
           <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-100 flex items-center">
              <div className="bg-purple-100 p-3 rounded-md mr-4">
                <FileVideo className="text-purple-600 w-6 h-6" />
              </div>
              <div>
                <p className="text-sm text-gray-500">Video Name Match</p>
                <p className="text-xl font-bold">Auto-Enabled</p>
              </div>
           </div>
           <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-100 flex items-center">
              <div className="bg-green-100 p-3 rounded-md mr-4">
                <CheckCircle className="text-green-600 w-6 h-6" />
              </div>
              <div>
                <p className="text-sm text-gray-500">System Status</p>
                <p className="text-xl font-bold text-green-600">Online</p>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default DesktopDashboard;

