import React, { useState, useEffect, useCallback } from 'react';
import { UploadCloud, Clock, CheckCircle, RefreshCw, FileVideo, AlertCircle, Loader2 } from 'lucide-react';
import { CustomerRequest } from '../types';
import { getPendingRequests, uploadDocument } from '../services/api';
import { formatDistanceToNow } from 'date-fns';
import { MOTIVATIONAL_QUOTES } from '../constants';

const DesktopDashboard: React.FC = () => {
  const [requests, setRequests] = useState<CustomerRequest[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);
  const [motivation, setMotivation] = useState(MOTIVATIONAL_QUOTES[0]);

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    const data = await getPendingRequests();
    setRequests(data);
    setIsLoading(false);
  }, []);

  useEffect(() => {
    fetchData();
    // Poll every 10 seconds for new registrations
    const interval = setInterval(fetchData, 10000);
    return () => clearInterval(interval);
  }, [fetchData]);

  // Handle File Upload & Logic Match
  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Normalize filename (remove extension for matching)
    const rawFileName = file.name;
    const nameWithoutExt = rawFileName.substring(0, rawFileName.lastIndexOf('.')) || rawFileName;

    // FIND MATCH
    // We look for a pending request where the videoName is contained in the uploaded filename
    const match = requests.find(r => 
      r.status === 'pending' && 
      (nameWithoutExt.toLowerCase().includes(r.videoName.toLowerCase()) || 
       r.videoName.toLowerCase() === nameWithoutExt.toLowerCase())
    );

    if (match) {
      setUploadStatus(`Matching "${match.customerName}"... Uploading...`);
      const success = await uploadDocument(match.id, file, match.phoneNumber);

      if (success) {
        setUploadStatus(`Success! Sent to ${match.customerName}.`);
        setMotivation(MOTIVATIONAL_QUOTES[Math.floor(Math.random() * MOTIVATIONAL_QUOTES.length)]);
        await fetchData(); // Refresh list
        setTimeout(() => setUploadStatus(null), 3000);
      } else {
        setUploadStatus("Error: Failed to upload.");
      }
    } else {
      setUploadStatus(`No pending request matches file "${rawFileName}". Check spelling.`);
    }

    // Reset input
    e.target.value = '';
  };

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">

      {/* SIDEBAR: PENDING REQUESTS */}
      <div className="w-1/3 bg-white border-r border-gray-200 flex flex-col">
        <div className="p-5 border-b border-gray-200 bg-gray-50 flex justify-between items-center">
          <div>
            <h2 className="text-lg font-bold text-gray-800">Pending Queue</h2>
            <p className="text-sm text-gray-500">{requests.length} waiting for video</p>
          </div>
          <button onClick={fetchData} className="p-2 hover:bg-gray-200 rounded-full transition">
            <RefreshCw className={`w-5 h-5 text-gray-600 ${isLoading ? 'animate-spin' : ''}`} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-3">
          {requests.length === 0 ? (
            <div className="text-center py-10 text-gray-400">
              <CheckCircle className="w-12 h-12 mx-auto mb-2 opacity-50" />
              <p>All caught up! No pending requests.</p>
            </div>
          ) : (
            requests.map((req) => (
              <div key={req.id} className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm hover:shadow-md transition-shadow relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-1 h-full bg-orange-400"></div>
                <div className="ml-3">
                  <div className="flex justify-between items-start">
                    <h3 className="font-semibold text-gray-800">{req.customerName}</h3>
                    <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-600">
                      {req.videoName}
                    </span>
                  </div>
                  <div className="mt-2 flex items-center text-sm text-gray-500 space-x-4">
                    <span className="flex items-center">
                      <Clock className="w-3 h-3 mr-1" />
                      {formatDistanceToNow(new Date(req.requestedAt), { addSuffix: true })}
                    </span>
                    <span>{req.phoneNumber}</span>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* MAIN AREA: UPLOADER */}
      <div className="flex-1 flex flex-col p-8 relative">

        {/* TOP BAR: STATS & MOTIVATION */}
        <div className="mb-8 flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Upload Dashboard</h1>
            <p className="text-gray-500 mt-1">AWS T3 Small • n8n Connected</p>
          </div>

          <div className="bg-blue-600 text-white px-6 py-3 rounded-lg shadow-lg max-w-md animate-pulse">
             <p className="font-medium">✨ {motivation}</p>
          </div>
        </div>

        {/* UPLOAD ZONE */}
        <div className="flex-1 bg-white rounded-2xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center p-10 hover:border-blue-500 hover:bg-blue-50 transition-colors cursor-pointer relative group">
          <input 
            type="file" 
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            onChange={handleFileChange}
            accept="video/*,application/pdf,image/*"
          />

          <div className="text-center pointer-events-none transition-transform group-hover:scale-105 duration-200">
            <div className="bg-blue-100 p-6 rounded-full inline-block mb-4">
              <UploadCloud className="w-16 h-16 text-blue-600" />
            </div>
            <h3 className="text-2xl font-bold text-gray-800 mb-2">Drop Video File Here</h3>
            <p className="text-gray-500 max-w-md mx-auto">
              System will automatically match the filename with the "Pending Queue" on the left and send via WhatsApp.
            </p>
          </div>

          {/* UPLOAD STATUS OVERLAY */}
          {uploadStatus && (
            <div className="absolute inset-0 bg-white/90 z-20 flex flex-col items-center justify-center backdrop-blur-sm rounded-2xl">
              {uploadStatus.includes("Error") || uploadStatus.includes("No pending") ? (
                 <AlertCircle className="w-16 h-16 text-red-500 mb-4" />
              ) : (
                 <Loader2 className="w-16 h-16 text-blue-600 animate-spin mb-4" />
              )}
              <h3 className={`text-xl font-bold ${uploadStatus.includes("Error") ? 'text-red-600' : 'text-gray-800'}`}>
                {uploadStatus}
              </h3>
            </div>
          )}
        </div>

        <div className="mt-6 grid grid-cols-3 gap-6">
           <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-100 flex items-center">
              <div className="bg-orange-100 p-3 rounded-md mr-4">
                <Clock className="text-orange-600 w-6 h-6" />
              </div>
              <div>
                <p className="text-sm text-gray-500">Pending</p>
                <p className="text-xl font-bold">{requests.length}</p>
              </div>
           </div>
           <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-100 flex items-center">
              <div className="bg-purple-100 p-3 rounded-md mr-4">
                <FileVideo className="text-purple-600 w-6 h-6" />
              </div>
              <div>
                <p className="text-sm text-gray-500">Video Name Match</p>
                <p className="text-xl font-bold">Auto-Enabled</p>
              </div>
           </div>
           <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-100 flex items-center">
              <div className="bg-green-100 p-3 rounded-md mr-4">
                <CheckCircle className="text-green-600 w-6 h-6" />
              </div>
              <div>
                <p className="text-sm text-gray-500">System Status</p>
                <p className="text-xl font-bold text-green-600">Online</p>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default DesktopDashboard;

