        </div>
      </div>

      {/* MAIN CONTENT AREA */}
      <div className="flex-1 flex flex-col p-8 relative z-10">

        {/* HEADER */}
        <div className="flex justify-between items-start mb-8">
           <div>
             <h1 className="text-3xl font-bold text-white drop-shadow-md">Dashboard</h1>
