           <div className="w-full max-w-2xl aspect-[16/9] relative group">
              <div className="absolute inset-0 bg-gradient-to-tr from-blue-500/20 to-purple-500/20 rounded-3xl blur-xl transition-opacity opacity-50 group-hover:opacity-100"></div>

              <div className="relative h-full glass rounded-3xl border-2 border-dashed border-white/30 hover:border-white/60 transition-all flex flex-col items-center justify-center cursor-pointer overflow-hidden">
                <input 
                  type="file" 
