               <ArrowLeft className="w-5 h-5" />
            </Link>
            <div>
              <h1 className="font-bold text-lg text-slate-800 tracking-tight">Queue</h1>
              <p className="text-xs text-slate-400 font-medium">Pending Approvals</p>
            </div>
            <div className="ml-auto bg-blue-50 text-blue-600 text-xs font-bold px-2.5 py-1 rounded-full">
              {requests.length}
            </div>
        </div>

        <div className="px-6 pb-4">
          <div className="relative group">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
            <input 
              type="text" 
              placeholder="Search customers..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-xl pl-10 pr-4 py-3 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:outline-none transition-all placeholder:text-slate-400"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-4 space-y-3 pb-4">
           {isLoading && requests.length === 0 && (
              <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin text-slate-300"/></div>
           )}

           {!isLoading && filteredRequests.length === 0 ? (
              <div className="text-center py-12 text-slate-400 flex flex-col items-center">
                <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mb-3">
                   <Filter className="w-5 h-5 opacity-50" />
                </div>
                <p className="text-sm font-medium">No requests found</p>
              </div>
           ) : (
              filteredRequests.map((req) => (
                <div key={req.id} className="group p-4 rounded-2xl bg-white border border-slate-100 hover:border-blue-500/30 hover:shadow-lg hover:shadow-blue-500/5 transition-all cursor-default select-none relative overflow-hidden">
                  <div className="flex justify-between items-start mb-2">
                    <span className="font-bold text-slate-700 text-sm">{req.customerName}</span>
                    <span className="text-[10px] font-medium text-slate-400 bg-slate-50 px-2 py-1 rounded-full">{formatDistanceToNow(new Date(req.requestedAt), { addSuffix: true })}</span>
                  </div>
                  <div className="flex items-center text-xs text-slate-500">
                    <div className="w-6 h-6 rounded-full bg-blue-50 flex items-center justify-center mr-2 shrink-0">
                       <FileVideo className="w-3 h-3 text-blue-500" />
                    </div>
                    <span className="font-medium truncate text-slate-600">{req.videoName}</span>
                  </div>
                </div>
              ))
           )}
        </div>

        <div className="p-4 border-t border-slate-100 bg-white">
           <button onClick={fetchData} className="flex items-center justify-center w-full py-3 bg-slate-900 hover:bg-slate-800 text-white rounded-xl text-sm font-medium transition-all shadow-md shadow-slate-200 active:scale-[0.98]">
              <RefreshCw className={`w-4 h-4 mr-2 ${isLoading ? 'animate-spin' : ''}`} /> Sync Queue
